#define _GNU_SOURCE
#include <linux/perf_event.h>
#include <sys/syscall.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>

static void ring_read(char *ring, size_t size, uint64_t at, void *dst, size_t n) {
    size_t offset=at%size, first=size-offset;
    if (first>n) first=n;
    memcpy(dst,ring+offset,first);
    if(first<n) memcpy((char*)dst+first,ring,n-first);
}
int main(int argc,char **argv) {
    if(argc<3) return 2;
    pid_t child=fork();
    if(child<0) {perror("fork");return 1;}
    if(child==0) {raise(SIGSTOP);execv(argv[2],argv+2);perror("execv");_exit(1);}
    int status;waitpid(child,&status,WUNTRACED);
    struct perf_event_attr attr={0};
    attr.size=sizeof(attr);attr.type=PERF_TYPE_SOFTWARE;attr.config=PERF_COUNT_SW_CPU_CLOCK;
    attr.sample_period=2000000;attr.sample_type=PERF_SAMPLE_IP;
    attr.disabled=1;attr.enable_on_exec=1;attr.exclude_kernel=1;attr.exclude_hv=1;
    int fd=syscall(SYS_perf_event_open,&attr,child,-1,-1,0);
    if(fd<0) {perror("perf_event_open");kill(child,SIGKILL);waitpid(child,&status,0);return 1;}
    size_t page=sysconf(_SC_PAGESIZE), size=page*256;
    void *mapped=mmap(NULL,page+size,PROT_READ|PROT_WRITE,MAP_SHARED,fd,0);
    if(mapped==MAP_FAILED) {perror("mmap");kill(child,SIGKILL);waitpid(child,&status,0);return 1;}
    kill(child,SIGCONT);waitpid(child,&status,0);
    struct perf_event_mmap_page *meta=mapped;
    uint64_t head=__atomic_load_n(&meta->data_head,__ATOMIC_ACQUIRE),tail=meta->data_tail;
    if(head-tail>size) {fprintf(stderr,"ring overflow\n");return 1;}
    char *ring=(char*)mapped+page;FILE *out=fopen(argv[1],"w");
    if(!out) {perror("fopen");return 1;}
    size_t samples=0;uint64_t lost=0;
    while(tail<head) {
        struct perf_event_header header;ring_read(ring,size,tail,&header,sizeof(header));
        if(header.size<sizeof(header)||tail+header.size>head) {fprintf(stderr,"bad record\n");return 1;}
        if(header.type==PERF_RECORD_SAMPLE) {uint64_t ip;ring_read(ring,size,tail+sizeof(header),&ip,8);fprintf(out,"%llx\n",(unsigned long long)ip);samples++;}
        if(header.type==PERF_RECORD_LOST) {uint64_t n;ring_read(ring,size,tail+sizeof(header)+8,&n,8);lost+=n;}
        tail+=header.size;
    }
    fclose(out);munmap(mapped,page+size);close(fd);
    fprintf(stderr,"samples=%zu lost=%llu child_status=%d\n",samples,(unsigned long long)lost,status);
    return !WIFEXITED(status)||WEXITSTATUS(status)!=0||lost!=0;
}
